MATCH (r:River)
WHERE EXISTS {
  MATCH (r)-[:flowsThrough]->(c:Country)
  WHERE c.name = 'Kazakhstan'
} OR EXISTS {
  MATCH (r)-[:partOf]->(b:DrainageBasin)
  WHERE b.name = 'Irtysh basin'
}
RETURN r.name AS river_name;

MATCH (l:Lake {name: 'Lake Sartlan'})
OPTIONAL MATCH (r:River)-[:flowsInto]->(l)
WITH l, COLLECT(DISTINCT r) AS rivers_into_lake

// Step 1: Find all countries that contain 'Lake Sartlan' directly or via rivers flowing into it
MATCH (r:River)-[:flowsThrough]->(c:Country)
WHERE r IN rivers_into_lake
WITH COLLECT(DISTINCT c) AS lake_countries

// Step 2: Find all drainage basins located in those same countries
// Note: Based on schema, DrainageBasin is not directly connected to Country.
// We infer basin-country relationship via: River(partOf)->DrainageBasin and River(flowsThrough)->Country
MATCH (rb:River)-[:partOf]->(db:DrainageBasin)
MATCH (rb)-[:flowsThrough]->(c2:Country)
WHERE c2 IN lake_countries

// Step 3: Aggregate by basin and count unique countries
RETURN db.name AS drainage_basin_name, COUNT(DISTINCT c2.name) AS num_countries
ORDER BY drainage_basin_name
